1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.dominio.ContextoPedido;
4	import com.loja.checkout.dominio.Registro;
5	import com.loja.checkout.dominio.clube.NivelClube;
6	import com.loja.checkout.dominio.cupom.Cupom;
7	import com.loja.checkout.dominio.entrega.ModalidadeEntrega;
8	import com.loja.checkout.dominio.pagamento.AjustePagamento;
9	import com.loja.checkout.dominio.pagamento.FormaPagamento;
10	import com.loja.checkout.dto.ItemDTO;
11	import com.loja.checkout.dto.PedidoRequest;
12	import com.loja.checkout.dto.ResumoResponse;
13	import com.loja.checkout.erro.CodigoErro;
14	import com.loja.checkout.erro.PedidoInvalidoException;
15	import com.loja.checkout.util.Dinheiro;
16	import org.springframework.stereotype.Service;
17	
18	import java.math.BigDecimal;
19	import java.util.List;
20	import java.util.Map;
21	
22	@Service
23	public class ResumoCompraService {
24	
25	    private static final Map<String, BigDecimal> PERCENTUAL_SEGURO_POR_REGIAO = Map.of(
26	            "SUDESTE", new BigDecimal("0.01"),
27	            "SUL", new BigDecimal("0.01"),
28	            "CENTRO_OESTE", new BigDecimal("0.015"),
29	            "NORTE", new BigDecimal("0.025"),
30	            "NORDESTE", new BigDecimal("0.02")
31	    );
32	
33	    private final Registro<ModalidadeEntrega> modalidades;
34	    private final Registro<Cupom> cupons;
35	    private final Registro<NivelClube> niveisClube;
36	    private final Registro<FormaPagamento> formasPagamento;
37	
38	    public ResumoCompraService(List<ModalidadeEntrega> modalidades, List<Cupom> cupons,
39	                                List<NivelClube> niveisClube, List<FormaPagamento> formasPagamento) {
40	        this.modalidades = new Registro<>(modalidades, ModalidadeEntrega::codigo,
41	                () -> new PedidoInvalidoException(CodigoErro.MODALIDADE_INVALIDA));
42	        this.cupons = new Registro<>(cupons, Cupom::codigo,
43	                () -> new PedidoInvalidoException(CodigoErro.CUPOM_INVALIDO));
44	        this.niveisClube = new Registro<>(niveisClube, NivelClube::codigo,
45	                () -> new PedidoInvalidoException(CodigoErro.NIVEL_CLUBE_INVALIDO));
46	        this.formasPagamento = new Registro<>(formasPagamento, FormaPagamento::codigo,
47	                () -> new PedidoInvalidoException(CodigoErro.FORMA_PAGAMENTO_INVALIDA));
48	    }
49	
50	    public ResumoResponse calcular(PedidoRequest pedido) {
51	        validarItens(pedido.itens());
52	        NivelClube nivelClube = niveisClube.buscar(pedido.nivelClube());
53	        BigDecimal percentualSeguro = buscarPercentualSeguro(pedido.regiao());
54	        ModalidadeEntrega modalidadeEntrega = modalidades.buscar(pedido.modalidadeEntrega());
55	
56	        BigDecimal subtotalProdutos = calcularSubtotal(pedido.itens());
57	        BigDecimal pesoTotalKg = calcularPesoTotal(pedido.itens());
58	        ContextoPedido contexto = new ContextoPedido(pedido.itens(), subtotalProdutos, pesoTotalKg);
59	
60	        modalidadeEntrega.validarDisponibilidade(pesoTotalKg);
61	        BigDecimal freteBase = modalidadeEntrega.calcularFrete(pesoTotalKg);
62	        BigDecimal frete = Dinheiro.arredondar(nivelClube.freteGratis() ? BigDecimal.ZERO : freteBase);
63	
64	        BigDecimal descontoCupom = BigDecimal.ZERO;
65	        if (pedido.cupom() != null) {
66	            Cupom cupom = cupons.buscar(pedido.cupom());
67	            cupom.validarAplicavel(contexto);
68	            descontoCupom = Dinheiro.arredondar(cupom.calcularDesconto(contexto, frete));
69	        }
70	
71	        BigDecimal seguro = Dinheiro.arredondar(subtotalProdutos.multiply(percentualSeguro));
72	
73	        BigDecimal totalPedido = Dinheiro.arredondar(
74	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
75	
76	        FormaPagamento formaPagamento = formasPagamento.buscar(pedido.formaPagamento());
77	        int parcelas = pedido.parcelas() == null ? 1 : pedido.parcelas();
78	        formaPagamento.validarParcelas(parcelas);
79	        formaPagamento.validarDisponibilidade(totalPedido);
80	        AjustePagamento ajustePagamento = formaPagamento.calcular(totalPedido, parcelas);
81	
82	        BigDecimal creditoProximaCompra = Dinheiro.arredondar(
83	                subtotalProdutos.multiply(nivelClube.percentualCredito()));
84	        boolean brinde = nivelClube.concedeBrinde(subtotalProdutos);
85	
86	        return new ResumoResponse(
87	                subtotalProdutos,
88	                descontoCupom,
89	                frete,
90	                modalidadeEntrega.prazoDias(),
91	                seguro,
92	                Dinheiro.arredondar(ajustePagamento.ajuste()),
93	                Dinheiro.arredondar(ajustePagamento.totalFinal()),
94	                parcelas,
95	                Dinheiro.arredondar(ajustePagamento.valorParcela()),
96	                creditoProximaCompra,
97	                brinde
98	        );
99	    }
100	
101	    private void validarItens(List<ItemDTO> itens) {
102	        if (itens == null || itens.isEmpty()) {
103	            throw new PedidoInvalidoException(CodigoErro.PEDIDO_INVALIDO);
104	        }
105	        for (ItemDTO item : itens) {
106	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
107	                    || item.quantidade() == null || item.quantidade() <= 0
108	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
109	                throw new PedidoInvalidoException(CodigoErro.PEDIDO_INVALIDO);
110	            }
111	        }
112	    }
113	
114	    private BigDecimal buscarPercentualSeguro(String regiao) {
115	        BigDecimal percentual = regiao == null ? null : PERCENTUAL_SEGURO_POR_REGIAO.get(regiao);
116	        if (percentual == null) {
117	            throw new PedidoInvalidoException(CodigoErro.REGIAO_INVALIDA);
118	        }
119	        return percentual;
120	    }
121	
122	    private BigDecimal calcularSubtotal(List<ItemDTO> itens) {
123	        BigDecimal subtotal = BigDecimal.ZERO;
124	        for (ItemDTO item : itens) {
125	            subtotal = subtotal.add(item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
126	        }
127	        return Dinheiro.arredondar(subtotal);
128	    }
129	
130	    private BigDecimal calcularPesoTotal(List<ItemDTO> itens) {
131	        BigDecimal peso = BigDecimal.ZERO;
132	        for (ItemDTO item : itens) {
133	            peso = peso.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
134	        }
135	        return peso;
136	    }
137	}
