4	import com.loja.checkout.erro.PedidoInvalidoException;
5	import com.loja.checkout.util.Dinheiro;
6	import org.springframework.stereotype.Component;
7	
8	import java.math.BigDecimal;
9	
10	@Component
11	public class Cartao implements FormaPagamento {
12	
13	    private static final int PARCELAS_SEM_JUROS = 3;
14	    private static final int PARCELAS_MAXIMAS = 12;
15	    private static final double TAXA_MENSAL = 0.0199;
16	
17	    @Override
18	    public String codigo() {
19	        return "CARTAO";
20	    }
21	
22	    @Override
23	    public void validarParcelas(int parcelas) {
24	        if (parcelas < 1 || parcelas > PARCELAS_MAXIMAS) {
25	            throw new PedidoInvalidoException(CodigoErro.PARCELAMENTO_INVALIDO);
26	        }
27	    }
28	
29	    @Override
30	    public AjustePagamento calcular(BigDecimal totalPedido, int parcelas) {
31	        if (parcelas <= PARCELAS_SEM_JUROS) {
32	            BigDecimal valorParcela = Dinheiro.arredondar(totalPedido.divide(BigDecimal.valueOf(parcelas), 10, java.math.RoundingMode.HALF_EVEN));
33	            return new AjustePagamento(BigDecimal.ZERO, totalPedido, valorParcela);
34	        }
35	        double total = totalPedido.doubleValue();
36	        double fator = 1 - Math.pow(1 + TAXA_MENSAL, -parcelas);
37	        double parcelaBruta = total * TAXA_MENSAL / fator;
38	        BigDecimal valorParcela = Dinheiro.arredondar(BigDecimal.valueOf(parcelaBruta));
39	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
40	        BigDecimal ajuste = totalFinal.subtract(totalPedido);
41	        return new AjustePagamento(ajuste, totalFinal, valorParcela);
42	    }
43	}
